#include <random>
#include <vector>
#include <algorithm>
#include "algorithms.h"

//==========================================
// BENCHMARK MODULE (HOA 11 and 14: measuring and comparing algorithms)
// Runs the six sorts on the same data and reports the time (std::chrono), the comparisons and the moves.
// Also compares linear search and binary search by the number of comparisons.
// The data is made with a FIXED seed, so a run can be repeated and the numbers compared.
//
// Used by the "Algorithm lab" screen in screens_lab.h and by tests/test_main.cpp.
//==========================================

// the shape of the input, the same algorithm behaves very differently on each
enum DataShape {
    SHAPE_RANDOM = 0,
    SHAPE_SORTED,
    SHAPE_REVERSED,
    SHAPE_FEW_UNIQUE,       // many equal items
    SHAPE_COUNT
};

//--- dataShapeName --------------------------------------------------------------------------------
// What    : The display name of a data shape (random, sorted, reversed, few unique).
// Returns : the name
// Used by : doLab (screens.h)
//--------------------------------------------------------------------------------------------------
inline const char* dataShapeName(DataShape shape) {
    switch (shape) {
        case SHAPE_RANDOM:     return "Random";
        case SHAPE_SORTED:     return "Already sorted";
        case SHAPE_REVERSED:   return "Reversed";
        case SHAPE_FEW_UNIQUE: return "Few unique values";
        default:               return "?";
    }
}

//--- makeBenchmarkData ----------------------------------------------------------------------------
// What    : Generates test numbers of the chosen shape. The seed is fixed, so a run can be
//           repeated.
// Returns : the numbers
// Used by : benchmarkAll, doShowcase (screens.h)
//--------------------------------------------------------------------------------------------------
inline std::vector<int> makeBenchmarkData(int n, DataShape shape, unsigned seed = 2026) {
    std::vector<int> data((size_t)n);
    std::mt19937 rng(seed);
    for (int i = 0; i < n; i++) {
        switch (shape) {
            case SHAPE_SORTED:     data[(size_t)i] = i; break;
            case SHAPE_REVERSED:   data[(size_t)i] = n - i; break;
            case SHAPE_FEW_UNIQUE: data[(size_t)i] = (int)(rng() % 10); break;
            default:               data[(size_t)i] = (int)(rng() % 1000000); break;
        }
    }
    return data;
}

struct BenchmarkRow {
    SortAlgo algo = ALGO_BUBBLE;
    bool skipped = false;           // quadratic algorithm on a very large input
    bool correct = false;           // the result was checked to be sorted
    double ms = 0;
    SortStats stats;
};

// sorts a COPY of the data with one algorithm
//--- benchmarkSort --------------------------------------------------------------------------------
// What    : Sorts a copy of the data with one algorithm and records the time, the comparisons, the
//           moves and whether the result is sorted. Quadratic sorts are skipped above the size
//           limit.
// Returns : one benchmark row
// Used by : benchmarkAll
//--------------------------------------------------------------------------------------------------
inline BenchmarkRow benchmarkSort(SortAlgo algo, const std::vector<int>& original) {
    BenchmarkRow row;
    row.algo = algo;
    int n = (int)original.size();
    if (sortAlgoIsQuadratic(algo) && n > QUADRATIC_SORT_LIMIT) {
        row.skipped = true;
        return row;
    }
    std::vector<int> copy = original;
    auto less = [](int a, int b) { return a < b; };
    Stopwatch watch;
    sortWith(algo, copy.data(), n, less, &row.stats);
    row.ms = watch.elapsedMs();
    row.correct = isSorted(copy.data(), n, less);
    return row;
}

// every algorithm on the same data
//--- benchmarkAll ---------------------------------------------------------------------------------
// What    : Runs all six sorts on the same generated data.
// Returns : six benchmark rows
// Used by : doLab (screens.h), doShowcase (screens.h)
//--------------------------------------------------------------------------------------------------
inline std::vector<BenchmarkRow> benchmarkAll(int n, DataShape shape) {
    std::vector<int> data = makeBenchmarkData(n, shape);
    std::vector<BenchmarkRow> rows;
    for (int a = 0; a < ALGO_COUNT; a++) rows.push_back(benchmarkSort((SortAlgo)a, data));
    return rows;
}

struct SearchBenchmark {
    int n = 0;
    long long linearComparisons = 0;
    long long binaryComparisons = 0;
};

// looks for the LAST item of a sorted array with both searches (the worst case for linear search)
//--- benchmarkSearch ------------------------------------------------------------------------------
// What    : Looks for the last item of a sorted array with linear and binary search, which is the
//           worst case of linear search, and counts the comparisons.
// Returns : both comparison counts
// Used by : doLab (screens.h), doShowcase (screens.h)
//--------------------------------------------------------------------------------------------------
inline SearchBenchmark benchmarkSearch(int n) {
    SearchBenchmark result;
    result.n = n;
    if (n <= 0) return result;
    std::vector<int> data((size_t)n);
    for (int i = 0; i < n; i++) data[(size_t)i] = i * 2;
    int key = data[(size_t)n - 1];
    linearSearch(data.data(), n, key, &result.linearComparisons);
    binarySearch(data.data(), n, key, [](int a, int b) { return a < b; }, &result.binaryComparisons);
    return result;
}

#endif //STEAM_BENCHMARK_H
